package com.bank.recon.service;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

// Counts contiguous day-stretches whose net flow equals the target.
public class ReconciliationCounter {
    private static final Logger log = Logger.getLogger(ReconciliationCounter.class.getName());

    public int countBalancedStretches(int[] flows, int target) {
        if (flows == null || flows.length == 0) {
            return 0;
        }
        Map<Long, Integer> prefixCounts = new HashMap<>();
        prefixCounts.put(0L, 1); // empty prefix: enables stretches starting at index 0
        long prefix = 0;
        int count = 0;

        for (int i = 0; i < flows.length; i++) {
            prefix += flows[i];
            int add = prefixCounts.getOrDefault(prefix - target, 0);
            if (add > 0) {
                final int idx = i, a = add;
                log.fine(() -> "At day " + idx + ", found " + a
                        + " stretch(es) ending here netting " + target);
            }
            count += add;
            prefixCounts.merge(prefix, 1, Integer::sum);
        }
        final int result = count;
        log.info(() -> "Balanced stretches netting " + target + " over "
                + Arrays.toString(flows) + " = " + result);
        return count;
    }
}
