// ─── File: src/main/java/com/bank/recon/SubarraySumEqualsKDemo.java ───
package com.bank.recon;

import com.bank.recon.model.Account;
import com.bank.recon.service.ReconciliationCounter;

import java.math.BigDecimal;
import java.util.Date;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class SubarraySumEqualsKDemo {
    private static final Logger log = Logger.getLogger(SubarraySumEqualsKDemo.class.getName());

    public static void main(String[] args) {
        setupLogging();
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        ReconciliationCounter counter = new ReconciliationCounter();
        int target = 0;

        int[] rajeshFlows = {1, -1, 5, -5, 3}; // stretches netting 0: [1,-1],[5,-5],[1,-1,5,-5]
        log.info(() -> rajesh.getHolderName() + " (" + rajesh.getAccountId() + ") flows");
        int r1 = counter.countBalancedStretches(rajeshFlows, target);
        log.info(() -> rajesh.getHolderName() + " balanced stretches = " + r1);

        int[] priyaFlows = {3, 4, 7, 2}; // all positive, none net to 0
        log.info(() -> priya.getHolderName() + " (" + priya.getAccountId() + ") flows");
        int r2 = counter.countBalancedStretches(priyaFlows, target);
        log.info(() -> priya.getHolderName() + " balanced stretches = " + r2);
    }

    private static void setupLogging() {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.FINE);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.FINE);
    }

    static class BankLogFormatter extends Formatter {
        @Override
        public String format(LogRecord r) {
            return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                    new Date(r.getMillis()), r.getLevel(), r.getMessage());
        }
    }
}
